var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();var names=new[]{"Player","Weapon_Manager","Pickup_Pool_Manager","InfiniteMap_Manager","EnemySpawner_Manager","LevelProgressionManager"};var lines=new System.Collections.Generic.List<string>();
foreach(var name in names){var go=scene.GetRootGameObjects().SelectMany(r=>r.GetComponentsInChildren<UnityEngine.Transform>(true)).Select(t=>t.gameObject).FirstOrDefault(g=>g.name==name);if(go==null){lines.Add(name+" NOT FOUND");continue;}lines.Add(name+" components="+string.Join(",",go.GetComponents<Component>().Where(c=>c!=null).Select(c=>c.GetType().Name)));foreach(var c in go.GetComponents<Component>().Where(c=>c!=null)){var so=new UnityEditor.SerializedObject(c);var p=so.GetIterator();while(p.NextVisible(true)){if(p.propertyType==UnityEditor.SerializedPropertyType.ObjectReference)lines.Add("  "+c.GetType().Name+"."+p.propertyPath+"="+(p.objectReferenceValue?p.objectReferenceValue.name:"NULL"));}}}
return string.Join("\n",lines);
